// Des: Find, launch and stop a local Chrome or Edge for CDP
// Flo: find exe > dedicated profile dir > spawn with port 0 > read DevToolsActivePort > list targets over /json > kill by child handle
// I/O: config paths (caller) > Brow (child, port, profile); page websocket path; stop frees everything
// ===================================================================
const std = @import("std"); const netz = std.Io.net; const mem2 = std.mem; const builtin = @import("builtin"); const cdp2 = @import("nt-brow-cdpz.zig");
const CF = .{ .actf = "DevToolsActivePort", .winp = @as([]const []const u8, &.{ "C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe", "C:\\Program Files (x86)\\Google\\Chrome\\Application\\chrome.exe", "C:\\Program Files (x86)\\Microsoft\\Edge\\Application\\msedge.exe", "C:\\Program Files\\Microsoft\\Edge\\Application\\msedge.exe" }), .linp = @as([]const []const u8, &.{ "/usr/bin/google-chrome", "/usr/bin/google-chrome-stable", "/usr/bin/chromium", "/usr/bin/chromium-browser", "/snap/bin/chromium", "/usr/bin/microsoft-edge" }), .macp = @as([]const []const u8, &.{ "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome", "/Applications/Microsoft Edge.app/Contents/MacOS/Microsoft Edge" }), .poll = 100, .maxr = 1 << 20 };
const winx = struct { extern "kernel32" fn GetProcessId(hdr2: std.os.windows.HANDLE) callconv(.winapi) u32; };
pub const Brow = struct { child: std.process.Child, port: u16, prof: []u8, gpaz: std.mem.Allocator, iozz: std.Io,
pub fn stop(self: *Brow) void { self.closSoft(); var tri2: u32 = 0; while (!portDead(self.gpaz, self.iozz, self.port) and tri2 < 50) : (tri2 += 1) std.Io.sleep(self.iozz, .fromMilliseconds(100), .awake) catch {}; if (!portDead(self.gpaz, self.iozz, self.port)) self.killHard(); self.child.kill(self.iozz); self.gpaz.free(self.prof); }
fn closSoft(self: *Brow) void { const body = httpGetz(self.gpaz, self.iozz, self.port, "/json/version") catch return; defer self.gpaz.free(body); var aren = std.heap.ArenaAllocator.init(self.gpaz); defer aren.deinit(); const valu = std.json.parseFromSliceLeaky(std.json.Value, aren.allocator(), body, .{}) catch return; if (valu != .object) return; const wsuz = valu.object.get("webSocketDebuggerUrl") orelse return; if (wsuz != .string) return; const sep2 = mem2.find(u8, wsuz.string, "/devtools/") orelse return; const conn = cdp2.connect(self.gpaz, self.iozz, self.port, wsuz.string[sep2..], 3000) catch return; defer conn.close(); const res4 = conn.call(self.gpaz, "Browser.close", "", 3000) catch return; self.gpaz.free(res4); }
fn killHard(self: *Brow) void { if (builtin.os.tag == .windows) { var buf4: [16]u8 = undefined; const pidz = std.fmt.bufPrint(&buf4, "{d}", .{winx.GetProcessId(self.child.id.?)}) catch return; var kchz = std.process.spawn(self.iozz, .{ .argv = &.{ "taskkill", "/PID", pidz, "/T", "/F" }, .stdin = .ignore, .stdout = .ignore, .stderr = .ignore }) catch return; _ = kchz.wait(self.iozz) catch {}; } } };
fn exists(iozz: std.Io, path: []const u8) bool { _ = std.Io.Dir.cwd().statFile(iozz, path, .{}) catch return false; return true; }
pub fn exezFind(gpaz: std.mem.Allocator, iozz: std.Io, pref: []const u8) !?[]u8 { if (pref.len > 0) { if (exists(iozz, pref)) return try gpaz.dupe(u8, pref); return null; } const list = switch (builtin.os.tag) { .windows => CF.winp, .macos => CF.macp, else => CF.linp }; for (list) |path| if (exists(iozz, path)) return try gpaz.dupe(u8, path); return null; }
pub fn httpGetz(gpaz: std.mem.Allocator, iozz: std.Io, port: u16, path: []const u8) ![]u8 { var addr = try netz.IpAddress.parse("127.0.0.1", port); const strm = try addr.connect(iozz, .{ .mode = .stream }); defer strm.close(iozz); var wbuf: [512]u8 = undefined; var wrtz = strm.writer(iozz, &wbuf); try wrtz.interface.print("GET {s} HTTP/1.1\r\nHost: 127.0.0.1:{d}\r\nAccept: */*\r\nConnection: close\r\n\r\n", .{ path, port }); try wrtz.interface.flush(); var rbuf: [4096]u8 = undefined; var rdr3 = strm.reader(iozz, &rbuf); const rdr2 = &rdr3.interface; const first = try rdr2.takeDelimiterInclusive('\n'); if (mem2.find(u8, first, " 200") == null) return error.BadReply; var clen: ?usize = null; while (true) { const line = try rdr2.takeDelimiterInclusive('\n'); if (line.len <= 2) break; if (std.ascii.startsWithIgnoreCase(line, "content-length:")) clen = std.fmt.parseInt(usize, mem2.trim(u8, line[15..], " \r\n"), 10) catch null; } if (clen) |con2| { if (con2 > CF.maxr) return error.BadReply; const body = try gpaz.alloc(u8, con2); errdefer gpaz.free(body); try rdr2.readSliceAll(body); return body; } return rdr2.allocRemaining(gpaz, .limited(CF.maxr)); }
pub fn launch(gpaz: std.mem.Allocator, iozz: std.Io, exe2: []const u8, prof: []const u8, head: bool, mill: u32) !Brow { try std.Io.Dir.cwd().createDirPath(iozz, prof); const actp = try std.fs.path.join(gpaz, &.{ prof, CF.actf }); defer gpaz.free(actp); std.Io.Dir.cwd().deleteFile(iozz, actp) catch {}; var argv: std.ArrayList([]const u8) = .empty; defer argv.deinit(gpaz); const uddz = try std.fmt.allocPrint(gpaz, "--user-data-dir={s}", .{prof}); defer gpaz.free(uddz); try argv.appendSlice(gpaz, &.{ exe2, "--remote-debugging-port=0", uddz, "--no-first-run", "--no-default-browser-check", "--disable-background-networking", "--disable-sync", "--disable-gpu", "--mute-audio" }); if (head) try argv.append(gpaz, "--headless=new"); try argv.append(gpaz, "about:blank"); var child = try std.process.spawn(iozz, .{ .argv = argv.items, .stdin = .ignore, .stdout = .ignore, .stderr = .ignore }); errdefer child.kill(iozz); var wai2: u32 = 0; while (wai2 <= mill) : (wai2 += CF.poll) { if (std.Io.Dir.cwd().readFileAlloc(iozz, actp, gpaz, .limited(512))) |tex2| { defer gpaz.free(tex2); var itrz = mem2.splitScalar(u8, tex2, '\n'); const pstr = mem2.trim(u8, itrz.next() orelse "", " \r"); if (std.fmt.parseInt(u16, pstr, 10)) |port| { if (port > 0) return .{ .child = child, .port = port, .prof = try gpaz.dupe(u8, prof), .gpaz = gpaz, .iozz = iozz }; } else |_| {} } else |_| {} std.Io.sleep(iozz, .fromMilliseconds(CF.poll), .awake) catch {}; } return error.LaunchTimeout; }
pub fn pageWszz(gpaz: std.mem.Allocator, iozz: std.Io, port: u16, mill: u32) ![]u8 { var wai2: u32 = 0; while (wai2 <= mill) : (wai2 += CF.poll * 2) { if (httpGetz(gpaz, iozz, port, "/json")) |body| { defer gpaz.free(body); var aren = std.heap.ArenaAllocator.init(gpaz); defer aren.deinit(); if (std.json.parseFromSliceLeaky(std.json.Value, aren.allocator(), body, .{})) |valu| { if (valu == .array) { for (valu.array.items) |item| { if (item != .object) continue; const typ2 = item.object.get("type") orelse continue; if (typ2 != .string or !mem2.eql(u8, typ2.string, "page")) continue; const wsuz = item.object.get("webSocketDebuggerUrl") orelse continue; if (wsuz != .string) continue; const sep2 = mem2.find(u8, wsuz.string, "/devtools/") orelse continue; return gpaz.dupe(u8, wsuz.string[sep2..]); } } } else |_| {} } else |_| {} std.Io.sleep(iozz, .fromMilliseconds(CF.poll * 2), .awake) catch {}; } return error.NoPage; }
pub fn portDead(gpaz: std.mem.Allocator, iozz: std.Io, port: u16) bool { _ = gpaz; var addr = netz.IpAddress.parse("127.0.0.1", port) catch return true; const strm = addr.connect(iozz, .{ .mode = .stream }) catch return true; strm.close(iozz); return false; }
